export function resolveCommanderId(id?: number, name?: string): number | undefined {
  if (id && id > 0 && COMMANDER_DATA[id]) {
    return id;
  }
  if (name) {
    const clean = name.trim().toLowerCase();
    if (COMMANDER_NAME_MAP[clean]) {
      return COMMANDER_NAME_MAP[clean];
    }
    const withoutP = clean.replace(/\s*\(p\)$/i, '').trim();
    if (COMMANDER_NAME_MAP[withoutP]) {
      return COMMANDER_NAME_MAP[withoutP];
    }
  }
  return undefined;
}

export function getCommanderMeta(id?: number, name?: string): CommanderMeta | undefined {
  const resolved = resolveCommanderId(id, name);
  if (resolved && COMMANDER_DATA[resolved]) {
    return COMMANDER_DATA[resolved];
  }
  return undefined;
}

export function getCommanderBackgroundUrl(rarity?: string): string {
  const r = (rarity || '').toLowerCase();
  if (r === 'legendary' || r === 'legend') {
    return './commanders/img_icon_HeroProfile_BGOrange.png';
  }
  if (r === 'epic') {
    return './commanders/img_icon_HeroProfile_BGPurple.png';
  }
  if (r === 'elite') {
    return './commanders/img_icon_HeroProfile_BGBlue.png';
  }
  if (r === 'advanced') {
    return './commanders/img_icon_HeroProfile_BGGreen.png';
  }
  return './commanders/img_icon_HeroProfile_BGWhite.png';
}

export function getCommanderFrameUrl(rarity?: string, isExpertised?: boolean): string {
  const r = (rarity || '').toLowerCase();
  if (isExpertised) {
    if (r === 'legendary' || r === 'legend') {
      return './commanders/img_icon_HeroProfile_BGMask_Orange.png';
    }
    if (r === 'epic') {
      return './commanders/img_icon_HeroProfile_BGMask_pink.png';
    }
  }
  return './commanders/img_icon_HeroProfile_BGMask.png';
}

export function getCommanderIconUrl(id?: number, name?: string): string {
  const meta = getCommanderMeta(id, name);
  if (meta && meta.icon) {
    return `./commanders/${meta.icon}`;
  }
  return './commanders/img_icon_HeroProfile_BGWhite2.png';
}

export function getCommanderWakeupSkillUrl(sprite?: string): string | undefined {
  if (sprite) {
    return `./commanders/skills/${sprite}`;
  }
  return undefined;
}

export function getCommanderPortraitUrl(id?: number, name?: string): string {
  const resolved = resolveCommanderId(id, name);
  if (resolved) {
    return `./commanders/portraits/${resolved}.png`;
  }
  return './commanders/portraits/placeholder.png';
}
